//! The kernel-hosted output: the app's execution is the kernel. The server is the template's fixed host over the native
//! kernel add-on, which answers every ask itself; the client hands the resolved schema to the `@almadar/ui` renderer
//! under a `KernelEngineProvider`.

use crate::backend::*;

const SHARED_DISPATCH: &str = r#"/**
 * The frame a host-run dispatch (a deferred `os` completion, a keyed `call-service` outcome) pushes to the tab that asked.
 *
 * @generated by Orbital Compiler (kernel host)
 * @packageDocumentation
 */

import type { OrbitalEventRequest, OrbitalEventResponse } from '@almadar/core';

export interface DispatchPushItem {
  type: 'dispatch';
  orbitalName: string;
  request: OrbitalEventRequest;
  response: OrbitalEventResponse;
}
"#;



/// Top-level keys the client never reads: `_metadata` and `ledger` are read only by the builders and
/// behavior composition, never by `OrbPreview`, the client kernel or the wasm kernel (which is handed
/// `{ name, orbitals }` only).
const CLIENT_UNREAD_PROGRAM_KEYS: [&str; 2] = ["_metadata", "ledger"];

/// Per-trait keys the client never reads: the wasm kernel's schema types carry them but no kernel
/// code reads them, and no client path reads `sourceEntityDefinition`.
const CLIENT_UNREAD_TRAIT_KEYS: [&str; 2] = ["effectRow", "sourceEntityDefinition"];

/// The resolved program as the browser receives it: route pages only (the client takes the routes, EXEC-ENDPOINT-5). The server keeps the whole program.
/// The program's files the program-independent web client reads at startup, by path under the
/// client's public root: `client.json` (the `ClientManifest`), `themes.css` (the declared themes, or
/// the runtime default preset when it declares none) and, when its browser kernel needs it,
/// `language.json`. `orb compile` writes them into `packages/client/public/`; `orb serve` serves them
/// beside the prebuilt client.
pub fn client_runtime_files(module: &OirModule, language: &str, ships_language: bool) -> Vec<(String, String)> {
    let (locale, direction) = match language {
        "ar" => ("ar", "rtl"),
        "sl" => ("sl", "ltr"),
        _ => ("en", "ltr"),
    };
    let (themes, default_theme, default_mode) = crate::codegen::client_themes(&module.themes, module.default_theme.as_deref());
    let manifest = serde_json::json!({
        "locale": locale,
        "direction": direction,
        "themes": themes,
        "defaultTheme": default_theme,
        "defaultMode": default_mode,
        "language": ships_language,
    });
    let default_preset;
    let styled: &[orbital_core_base::schema::types::ThemeDefinition] = if module.themes.is_empty() {
        default_preset = orbital_core_base::theme::ThemePresets::installed()
            .get(orbital_core_base::theme::DEFAULT_THEME_BASE)
            .cloned()
            .into_iter()
            .collect::<Vec<_>>();
        &default_preset
    } else {
        &module.themes
    };
    let mut css = String::new();
    for url in crate::codegen::theme_font_imports(styled) {
        css.push_str(&format!("@import url(\"{url}\");\n"));
    }
    for theme in styled {
        css.push_str(&crate::codegen::generate_theme_css(theme));
        css.push('\n');
    }
    let mut files = vec![
        ("client.json".to_string(), serde_json::to_string_pretty(&manifest).unwrap_or_default()),
        ("themes.css".to_string(), css),
    ];
    if ships_language {
        if let Ok(bundle) = orbital_core_base::language_data::language_bundle_json() {
            files.push(("language.json".to_string(), bundle));
        }
    }
    files
}

/// `program.client.orb`: the resolved program as the web client fetches it (keys sorted, without what no
/// client code path reads).
pub fn client_program_orb(schema: &orbital_core_base::schema::types::OrbitalSchema) -> serde_json::Result<String> {
    serde_json::to_string(&client_program(&orbital_core_eval::util::canonical_json(&serde_json::to_value(schema)?)))
}

pub(crate) fn client_program(program: &serde_json::Value) -> serde_json::Value {
    let mut projected = program.clone();
    let Some(root) = projected.as_object_mut() else {
        return projected;
    };
    for key in CLIENT_UNREAD_PROGRAM_KEYS {
        root.remove(key);
    }
    if let Some(orbitals) = root
        .get_mut("orbitals")
        .and_then(serde_json::Value::as_array_mut)
    {
        // The client serves routes only (EXEC-ENDPOINT-5): an orbital whose every page is a protocol endpoint is the server's.
        orbitals.retain(|orbital| {
            let pages = orbital.get("pages").and_then(serde_json::Value::as_array);
            !pages.is_some_and(|pages| !pages.is_empty() && pages.iter().all(|page| page.get("protocol").is_some()))
        });
        for orbital in orbitals {
            if let Some(pages) = orbital
                .get_mut("pages")
                .and_then(serde_json::Value::as_array_mut)
            {
                pages.retain(|page| page.get("protocol").is_none());
            }
            let traits = orbital
                .get_mut("traits")
                .and_then(serde_json::Value::as_array_mut);
            for trait_def in traits.into_iter().flatten() {
                if let Some(trait_def) = trait_def.as_object_mut() {
                    for key in CLIENT_UNREAD_TRAIT_KEYS {
                        trait_def.remove(key);
                    }
                }
            }
        }
    }
    // A browser kernel has no operator table: the sites of the effects its traits run travel with the program.
    let mut heads = std::collections::BTreeSet::new();
    collect_call_heads(root.get("orbitals").unwrap_or(&serde_json::Value::Null), &mut heads);
    let sites = orbital_core_base::runs_on::operator_sites(heads.iter().map(String::as_str));
    let mut metadata = serde_json::Map::new();
    if !sites.is_empty() {
        metadata.insert("operatorSites".to_string(), serde_json::json!(sites));
    }
    if let Some(facts) = orbital_core_base::language::registry::table_dispatch_facts() {
        metadata.insert("dispatchFacts".to_string(), serde_json::json!(facts));
    }
    if let Ok(rows) = orbital_core_base::protocols::table() {
        metadata.insert("protocols".to_string(), serde_json::json!(rows));
    }
    if !metadata.is_empty() {
        root.insert("_metadata".to_string(), serde_json::Value::Object(metadata));
    }
    projected
}

/// Every string at the head of a JSON array under `value`: the operator of each call the program spells.
fn collect_call_heads(value: &serde_json::Value, heads: &mut std::collections::BTreeSet<String>) {
    match value {
        serde_json::Value::Array(items) => {
            if let Some(serde_json::Value::String(head)) = items.first() {
                heads.insert(head.clone());
            }
            items.iter().for_each(|item| collect_call_heads(item, heads));
        }
        serde_json::Value::Object(map) => map.values().for_each(|item| collect_call_heads(item, heads)),
        _ => {}
    }
}

impl TypeScriptBackend {
    /// The shared barrel of a kernel-hosted app: the default exports plus the dispatch frame type.
    pub(crate) fn generate_shared_index_kernel(
        &self,
        named_types: &std::collections::BTreeMap<String, OirType>,
    ) -> InternalFile {
        let base = self.generate_shared_index(named_types);
        InternalFile::new(
            base.path,
            format!(
                "{}export * from './dispatch.js';\n",
                base.content
            ),
            GeneratedFileType::Barrel,
        )
    }

    /// The dispatch frame type the client reads.
    pub(crate) fn generate_shared_dispatch(&self) -> Vec<InternalFile> {
        if self.browser_schema.is_none() {
            return Vec::new();
        }
        vec![InternalFile::new("packages/shared/src/dispatch.ts", SHARED_DISPATCH, GeneratedFileType::Config)]
    }

    /// The served program (the app composed with `std-http-server`), the program the template server runs.
    pub(crate) fn generate_served_program(&self) -> Vec<InternalFile> {
        let Some(schema) = &self.served_schema else {
            return Vec::new();
        };
        let Ok(value) = serde_json::to_value(schema) else {
            return Vec::new();
        };
        let Ok(json) = serde_json::to_string(&orbital_core_eval::util::canonical_json(&value)) else {
            return Vec::new();
        };
        vec![InternalFile::new("packages/server/generated/program.orb", json, GeneratedFileType::Config)]
    }

    /// The kernel-hosted client: the loader and the `App` that renders the program on the kernel.
    pub(crate) fn generate_kernel_client(&self, module: &OirModule) -> Vec<InternalFile> {
        let ships_language = self.client_needs_language(module);
        let mut files: Vec<InternalFile> = Vec::new();
        files.extend(client_runtime_files(module, &self.schema_language, ships_language).into_iter().map(|(path, content)| {
            InternalFile::new(format!("packages/client/public/{path}"), content, GeneratedFileType::Config)
        }));
        files.extend(self.generate_client_program_files());
        files
    }

    /// The client's projection of the program, a static asset the template client fetches at startup.
    fn generate_client_program_files(&self) -> Vec<InternalFile> {
        let Some(schema) = &self.browser_schema else {
            return Vec::new();
        };
        let Ok(json) = client_program_orb(schema) else {
            return Vec::new();
        };
        vec![
            InternalFile::new(
                "packages/client/public/program.client.orb",
                json,
                GeneratedFileType::Config,
            ),
        ]
    }

    /// What a kernel-hosted compile could not do, reported with the output.
    /// The client may open a kernel over browser-stored rows: the program stores some, or it has lazy pages, whose
    /// behaviors load after compile and may store their own.
    fn client_needs_language(&self, module: &OirModule) -> bool {
        let has_lazy_pages = self
            .browser_schema
            .as_ref()
            .and_then(|schema| schema.lazy_pages.as_ref())
            .is_some_and(|pages| !pages.is_empty());
        has_lazy_pages || module.entities.iter().any(|entity| entity.browser)
    }

    pub(crate) fn kernel_host_warnings(&self, module: &OirModule) -> Vec<String> {
        let mut warnings = Vec::new();
        if self.browser_schema.is_none() {
            warnings.push("kernel host: no resolved schema was supplied, so the program is not embedded".to_string());
        }
        if self.target != "client" && self.served_schema.is_none() {
            warnings.push("kernel host: no served program was supplied, so the server has no program to run".to_string());
        }
        if self.target != "server" && self.client_needs_language(module) {
            if let Err(e) = orbital_core_base::language_data::language_bundle_json() {
                warnings.push(format!("kernel host: the program stores rows in the browser (or has lazy pages that may), but the installed language could not be read for its browser kernel ({}: {e})", e.code()));
            }
        }
        warnings
    }
}

#[cfg(test)]
mod client_program_tests {
    use super::client_program;
    use orbital_core_eval::util::canonical_json;
    use serde_json::json;

    fn program() -> serde_json::Value {
        json!({
            "name": "App",
            "_metadata": { "configProvenance": { "T": [] } },
            "ledger": { "entries": {} },
            "orbitals": [{
                "name": "O",
                "entity": { "name": "E" },
                "traits": [
                    { "name": "T", "effectRow": { "uses": [] }, "sourceEntityDefinition": { "name": "E" },
                      "emits": [{ "event": "X", "eventId": "evt_1", "description": "d" }],
                      "stateMachine": { "transitions": [{ "event": "X", "eventId": "evt_1" }] } },
                    { "ref": "Imported" }
                ]
            }]
        })
    }

    #[test]
    fn the_unread_keys_are_dropped_everywhere_they_occur() {
        let out = client_program(&program());
        let metadata: Vec<&String> = out["_metadata"].as_object().map(|m| m.keys().collect()).unwrap_or_default();
        assert_eq!(metadata, ["dispatchFacts", "protocols"], "the authored _metadata is dropped; only what a client kernel reads is written");
        assert!(out.get("ledger").is_none());
        let t = &out["orbitals"][0]["traits"][0];
        assert!(t.get("effectRow").is_none() && t.get("sourceEntityDefinition").is_none());
    }

    #[test]
    fn control_every_key_a_client_path_reads_survives() {
        let out = client_program(&program());
        let t = &out["orbitals"][0]["traits"][0];
        assert_eq!(t["emits"][0]["eventId"], "evt_1");
        assert_eq!(t["emits"][0]["description"], "d");
        assert_eq!(t["stateMachine"]["transitions"][0]["eventId"], "evt_1");
        assert_eq!(out["orbitals"][0]["traits"][1]["ref"], "Imported");
        assert_eq!(out["orbitals"][0]["entity"]["name"], "E");
    }

    #[test]
    fn an_orbital_reached_only_through_protocol_endpoints_is_not_projected() {
        let out = client_program(&json!({ "orbitals": [
            { "name": "Api", "pages": [{ "name": "Api", "protocol": "http" }], "traits": [{ "name": "Http1" }] },
            { "name": "Web", "pages": [{ "name": "Home", "path": "/" }], "traits": [{ "name": "Home" }] },
            { "name": "Lib", "traits": [{ "name": "Shared" }] },
            { "name": "Mixed", "pages": [{ "name": "Boot", "protocol": "boot" }, { "name": "Demo", "path": "/demo" }], "traits": [] }
        ] }));
        let names: Vec<&str> = out["orbitals"].as_array().unwrap().iter().map(|o| o["name"].as_str().unwrap()).collect();
        assert_eq!(names, ["Web", "Lib", "Mixed"], "control: route, page-less and mixed orbitals stay");
        assert_eq!(out["orbitals"][2]["pages"].as_array().unwrap().len(), 1);
    }

    #[test]
    fn the_sites_of_the_table_routed_effects_a_client_runs_travel_with_the_program() {
        let out = client_program(&json!({ "_metadata": { "configProvenance": {} }, "orbitals": [
            { "name": "Web", "pages": [{ "name": "Home", "path": "/" }], "traits": [{ "name": "Home", "stateMachine": { "transitions": [
                { "from": "a", "to": "a", "event": "INIT", "effects": [["behavior/catalog", { "paths": ["x"] }, { "emit": { "success": "LISTED" } }], ["when", true, ["program/print", "@payload.result"]], ["set", "@entity.x", 1]] }
            ] } }] }
        ] }));
        let sites = &out["_metadata"]["operatorSites"];
        assert_eq!(sites["behavior/catalog"], "server");
        assert_eq!(sites["program/print"], "server");
        assert!(sites.get("when").is_none(), "control: a pure form carries no site");
        assert!(out["_metadata"].get("configProvenance").is_none(), "the rest of _metadata stays unread");
    }

    #[test]
    fn control_a_client_running_only_kernel_built_in_effects_carries_no_site_table() {
        let out = client_program(&json!({ "orbitals": [
            { "name": "Web", "pages": [{ "name": "Home", "path": "/" }], "traits": [{ "name": "Home", "stateMachine": { "transitions": [
                { "from": "a", "to": "a", "event": "INIT", "effects": [["fetch", "Task", {}], ["navigate", "/x"]] }
            ] } }] }
        ] }));
        assert!(out["_metadata"].get("operatorSites").is_none(), "{out}");
    }

    #[test]
    fn the_dispatch_facts_a_browser_kernel_reads_travel_with_every_client_program() {
        let out = client_program(&json!({ "orbitals": [
            { "name": "Web", "pages": [{ "name": "Home", "path": "/" }], "traits": [{ "name": "Home" }] }
        ] }));
        let facts = orbital_core_base::language::registry::table_dispatch_facts().expect("the installed operator table");
        assert_eq!(out["_metadata"]["dispatchFacts"], serde_json::to_value(facts).unwrap());
        assert_eq!(out["_metadata"]["dispatchFacts"]["busExcluded"], json!(["INIT", "LOAD", "$MOUNT"]));
        assert_eq!(out["_metadata"]["dispatchFacts"]["targetOptions"], json!(["orbital", "targetTrait", "event"]));
    }

    #[test]
    fn the_protocol_table_a_browser_kernel_reads_travels_with_every_client_program() {
        let out = client_program(&json!({ "orbitals": [
            { "name": "Web", "pages": [{ "name": "Home", "path": "/" }], "traits": [{ "name": "Home" }] }
        ] }));
        let rows = orbital_core_base::protocols::table().expect("the installed protocol table");
        assert_eq!(out["_metadata"]["protocols"], serde_json::to_value(rows).unwrap());
        assert_eq!(out["_metadata"]["protocols"][1]["name"], "http");
        assert_eq!(out["_metadata"]["protocols"][1]["grant"], "net-listen");
    }

    #[test]
    fn edge_a_program_that_is_not_an_object_passes_through() {
        assert_eq!(client_program(&json!(null)), json!(null));
    }

    #[test]
    fn keys_are_sorted_at_every_depth_and_array_order_is_kept() {
        let out = canonical_json(&json!({ "b": 1, "a": { "z": [ { "y": 1, "x": 2 }, 0 ], "c": null } }));
        assert_eq!(
            serde_json::to_string(&out).unwrap(),
            r#"{"a":{"c":null,"z":[{"x":2,"y":1},0]},"b":1}"#
        );
    }

    #[test]
    fn edge_a_scalar_passes_through_unchanged() {
        assert_eq!(canonical_json(&json!("k")), json!("k"));
    }
}
